 document.querySelectorAll("[data-team-logo]").forEach(input=>input.onchange=async e=>{const file=e.target.files?.[0],id=input.dataset.teamLogo;if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){toast("El escudo debe ser JPG, PNG o WEBP de máximo 5 MB.","warning");return}try{const path=`teamAssets/${state.user.uid}/${id}/logo-${Date.now()}`,ref=storageRef(storage,path);await uploadBytes(ref,file,{contentType:file.type});const url=await getDownloadURL(ref);await updateDoc(doc(db,"teams",id),{logoURL:url,logoPath:path,updatedAt:serverTimestamp()});toast("Escudo actualizado.");renderPage()}catch(err){console.error(err);toast("No se pudo subir el escudo. Verifica Storage Rules.","warning")}});
