async function showLeague(id){
 let l=state.leagues.find(x=>x.id===id);
 try{if(!l){const ls=await getDoc(doc(db,"leagues",id));if(!ls.exists())throw new Error("No encontramos esta competición.");l={id,...ls.data()};}}
 catch(e){toast(e.message||"No se pudo cargar la competición.","warning");return}
 const host=document.getElementById("league-detail");if(!host)return;
 host.innerHTML='<section class="panel"><div class="muted">Cargando calendario y tabla...</div></section>';
 try{
  const [teamSnap,matchSnap]=await Promise.all([
   getDocs(query(collection(db,"teams"),where("leagueId","==",id))),
   getDocs(query(collection(db,"matches"),where("leagueId","==",id)))
  ]);
  const teams=new Map();
  teamSnap.forEach(d=>{const x=d.data(),approval=x.approvalStatus||(x.status==='active'?'approved':'pending');if(approval==='approved'&&x.status!=='rejected')teams.set(d.id,{id:d.id,name:x.name||x.teamName||"Equipo",logoURL:x.logoURL||""})});
  const matches=matchSnap.docs.map(d=>({id:d.id,...d.data()})).filter(m=>!['pending','rejected'].includes(String(m.approvalStatus||'').toLowerCase()));
  // Recuperar nombres desde los encuentros si algún equipo no aparece en la consulta.
  matches.forEach(m=>{
   if(m.homeTeamId&&!teams.has(m.homeTeamId))teams.set(m.homeTeamId,{id:m.homeTeamId,name:m.homeTeam||"Equipo local",logoURL:""});
   if(m.awayTeamId&&!teams.has(m.awayTeamId))teams.set(m.awayTeamId,{id:m.awayTeamId,name:m.awayTeam||"Equipo visitante",logoURL:""});
  });
  const pointsWin=Number(l.pointsWin??3),pointsDraw=Number(l.pointsDraw??1),pointsLoss=Number(l.pointsLoss??0);
  const table={};teams.forEach(t=>table[t.id]={...t,pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0});
  const finishedStatuses=["final","completed","finished"];
  matches.forEach(m=>{
   if(!finishedStatuses.includes(String(m.status||"").toLowerCase())||m.homeGoals==null||m.awayGoals==null)return;
   const h=table[m.homeTeamId],a=table[m.awayTeamId];if(!h||!a)return;
   const hg=Number(m.homeGoals),ag=Number(m.awayGoals);if(!Number.isFinite(hg)||!Number.isFinite(ag))return;
   h.pj++;a.pj++;h.gf+=hg;h.gc+=ag;a.gf+=ag;a.gc+=hg;
   if(hg>ag){h.pg++;a.pp++;h.pts+=pointsWin;a.pts+=pointsLoss}
   else if(hg<ag){a.pg++;h.pp++;a.pts+=pointsWin;h.pts+=pointsLoss}
   else{h.pe++;a.pe++;h.pts+=pointsDraw;a.pts+=pointsDraw}
  });
  const standings=Object.values(table).sort((a,b)=>b.pts-a.pts||(b.gf-b.gc)-(a.gf-a.gc)||b.gf-a.gf||a.name.localeCompare(b.name,"es"));
  const rounds=new Map();matches.sort((a,b)=>(Number(a.round)||999)-(Number(b.round)||999)||(a.kickoff?.seconds||0)-(b.kickoff?.seconds||0)).forEach(m=>{const r=Number(m.round)||0;if(!rounds.has(r))rounds.set(r,[]);rounds.get(r).push(m)});
  const matchCard=m=>{const done=finishedStatuses.includes(String(m.status||"").toLowerCase())&&m.homeGoals!=null&&m.awayGoals!=null;const kickoff=m.kickoff?.toDate?m.kickoff.toDate():null;const date=kickoff?kickoff.toLocaleString("es-MX",{dateStyle:"medium",timeStyle:"short"}):"Fecha y hora por confirmar";const dateValue=kickoff?`${kickoff.getFullYear()}-${String(kickoff.getMonth()+1).padStart(2,"0")}-${String(kickoff.getDate()).padStart(2,"0")}`:"";const timeValue=kickoff?`${String(kickoff.getHours()).padStart(2,"0")}:${String(kickoff.getMinutes()).padStart(2,"0")}`:"";return `<article class="fixture-card"><div class="fixture-team"><b>${esc(m.homeTeam||teams.get(m.homeTeamId)?.name||"Local")}</b></div><div class="fixture-score ${done?"is-final":""}">${done?`${Number(m.homeGoals)} – ${Number(m.awayGoals)}`:"VS"}</div><div class="fixture-team"><b>${esc(m.awayTeam||teams.get(m.awayTeamId)?.name||"Visitante")}</b></div><small>${esc(date)} · ${done?"Finalizado":esc(m.status||"Programado")}${m.venue?` · ${esc(m.venue)}`:""}</small>${isAdmin()?`<form class="fixture-admin-form" data-match-form="${m.id}"><label>Fecha<input type="date" name="date" value="${dateValue}"></label><label>Hora<input type="time" name="time" value="${timeValue}"></label><label>Cancha / sede<input name="venue" maxlength="120" value="${esc(m.venue||"")}" placeholder="Cancha municipal"></label><label>Goles local<input type="number" name="homeGoals" min="0" max="99" value="${m.homeGoals??""}"></label><label>Goles visitante<input type="number" name="awayGoals" min="0" max="99" value="${m.awayGoals??""}"></label><div class="fixture-form-actions"><button class="btn-secondary" type="submit">Guardar partido</button></div></form>`:""}</article>`};
  const roundMarkup=matches.length?[...rounds.entries()].map(([round,items])=>`<section class="fixture-round"><div class="fixture-round-head"><h4>${round?`Jornada ${round}`:"Encuentros sin jornada"}</h4><span>${items.length} partidos</span></div><div class="fixture-grid">${items.map(matchCard).join("")}</div></section>`).join(""):'<div class="empty-state">Todavía no hay encuentros guardados para esta competición. Si ya realizaste el sorteo, revisa que los partidos se hayan guardado con el mismo identificador de liga.</div>';
  host.innerHTML=`<section class="panel league-center"><div class="eyebrow green">CENTRO DE COMPETICIÓN</div><h2>${esc(l.name||"Competición")}</h2><p>${esc(l.season||"")} · ${esc(l.city||"")} · ${esc(l.branch||"")}</p><div class="league-center-stats"><div><b>${teams.size}</b><small>Equipos</small></div><div><b>${matches.length}</b><small>Encuentros</small></div><div><b>${rounds.size}</b><small>Jornadas</small></div><div><b>${matches.filter(m=>finishedStatuses.includes(String(m.status||"").toLowerCase())&&m.homeGoals!=null&&m.awayGoals!=null).length}</b><small>Finalizados</small></div></div><h3>Tabla de posiciones</h3><p class="form-hint">La clasificación se calcula con los marcadores guardados como finalizados. Puntuación: ${pointsWin} por victoria, ${pointsDraw} por empate y ${pointsLoss} por derrota.</p>${standings.length?`<div class="table-wrap"><table class="data-table standings-table"><thead><tr><th>#</th><th>Equipo</th><th>PJ</th><th>PG</th><th>PE</th><th>PP</th><th>GF</th><th>GC</th><th>DG</th><th>PTS</th></tr></thead><tbody>${standings.map((t,i)=>`<tr><td>${i+1}</td><td><b>${esc(t.name)}</b></td><td>${t.pj}</td><td>${t.pg}</td><td>${t.pe}</td><td>${t.pp}</td><td>${t.gf}</td><td>${t.gc}</td><td>${t.gf-t.gc}</td><td><b>${t.pts}</b></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">No hay equipos vinculados a esta competición.</div>'}<h3>Calendario de encuentros</h3>${roundMarkup}<div class="admin-actions"><button class="btn-secondary" type="button" data-close-league-center>Cerrar consulta</button></div></section>`;
  const close=host.querySelector("[data-close-league-center]");if(close)close.onclick=()=>{host.innerHTML=""};
  host.querySelectorAll("[data-match-form]").forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const date=String(f.get("date")||""),time=String(f.get("time")||"");const kickoffIso=date&&time?new Date(`${date}T${time}:00`).toISOString():"";const payload={matchId:form.dataset.matchForm,kickoffIso,venue:String(f.get("venue")||"").trim(),homeGoals:String(f.get("homeGoals")??""),awayGoals:String(f.get("awayGoals")??"")};try{const result=await httpsCallable(functions,"adminUpdateLeagueMatch")(payload);toast(result.data?.message||"Encuentro actualizado.");await showLeague(id)}catch(err){console.error(err);toast(err.message||"No se pudo actualizar el encuentro.","warning")}});
  host.scrollIntoView({behavior:"smooth",block:"start"});
 }catch(e){console.error("Error al mostrar competición:",e);host.innerHTML='<section class="panel"><div class="empty-state">No se pudieron consultar los equipos y encuentros. Revisa los permisos de lectura de Firestore.</div></section>'}
}

onAuthStateChanged(auth,async user=>{state.user=user;if(!user){state.admin=false;state.profile={};authView();return}try{const token=await getIdTokenResult(user,true);state.claims=token.claims;state.admin=token.claims.superadmin===true;const ref=doc(db,"users",user.uid),snap=await getDoc(ref);if(!snap.exists()){await setDoc(ref,{displayName:user.displayName||"",email:user.email||"",roles:[state.pendingInitialRole||"Aficionado"],status:"active",createdAt:serverTimestamp(),updatedAt:serverTimestamp()});state.profile={displayName:user.displayName||"",email:user.email,roles:[state.pendingInitialRole||"Aficionado"]}}else state.profile=snap.data();const playerSnap=await getDoc(doc(db,"players",user.uid)).catch(()=>null);if(playerSnap?.exists())state.profile={...state.profile,...playerSnap.data()};if(!Array.isArray(state.profile.roles))state.profile.roles=["Aficionado"];const hasClubAdmin=state.profile.roles.some(r=>r==="Administrador de club");if(hasClubAdmin){state.activeMode="manager";localStorage.setItem("cascarita-active-mode","manager")}else if(state.profile.roles.includes("Jugador")){state.activeMode="player";localStorage.setItem("cascarita-active-mode","player")}else{state.activeMode="public";localStorage.setItem("cascarita-active-mode","public")}state.page=state.activeMode==="manager"?"Administración del club":state.activeMode==="player"?"Inicio jugador":"Inicio";shell()}catch(e){console.error(e);toast("No se pudo cargar tu perfil o tus permisos.","warning");shell()}});
